import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0063: Scheme-Core Completeness for Self-Hosting","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0063-scheme-core-completeness.md","filePath":"vendored/handl/project/adrs/0063-scheme-core-completeness.md"}`),a={name:`handl/project/adrs/0063-scheme-core-completeness.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0063-scheme-core-completeness-for-self-hosting" tabindex="-1">ADR-0063: Scheme-Core Completeness for Self-Hosting <a class="header-anchor" href="#adr-0063-scheme-core-completeness-for-self-hosting" aria-label="Permalink to “ADR-0063: Scheme-Core Completeness for Self-Hosting”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Proposed</p><p>Gates <a href="./0044-language-as-data-and-runtime-split.html">ADR-0044 — Language as Data and Runtime Split</a> Phase 8 (self-hosting) and every downstream ADR that assumes handl can describe itself as a <code>Language</code> value (<a href="./0064-computational-language-authoring.html">0064</a>, <a href="./0065-derived-artifact-cache-and-compression.html">0065</a>, <a href="./0066-dependency-graph-chunking.html">0066</a>, <a href="./0067-chunk-certificates.html">0067</a>). Refines <a href="./0052-arrow-calculus-kernel.html">ADR-0052 — Arrow Calculus Kernel</a> and <a href="./0058-generic-data-driven-engines.html">ADR-0058 — Generic Data-Driven Engines</a>.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>ADR-0044 §&quot;Negative consequences&quot; names the single unsolved risk:</p><blockquote><p>The scheme combinator set + desugar rules are the crux and the risk. &quot;Semantics as data&quot; for a full language (call, match, handle, pipes, ternary, function literals, ...) is genuinely hard. The core combinator set must be small enough to interpret/compile efficiently yet expressive enough that surface constructs desugar to it without escaping to Rust. An incomplete combinator set or desugar layer forces <code>Foreign</code> escapes, which undermine the pure-data model.</p></blockquote><p>ADR-0052 replaced the lambda-flavored <code>Scheme</code> with the arrow-calculus kernel (<code>arr</code>/<code>&gt;&gt;&gt;</code>/<code>first</code>/<code>choice</code>/<code>loop</code>/<code>app</code>) and removed <code>vau</code>. ADR-0058 established that engines are fixed interpreters of data and that language-specific logic must migrate to desugar rules or scheme descriptions, not engine code.</p><p>Neither ADR proves the property that matters: <strong>the arrow-calculus core + desugar rules can describe handl&#39;s own semantics without <code>Foreign</code> escapes.</strong> Until that property holds, self-hosting (ADR-0044 Phase 8) is not real — a <code>handl-defining-handl</code> data file that needs <code>Foreign(&quot;parse&quot;)</code> or <code>Foreign(&quot;eval&quot;)</code> to describe its own evaluation is not self-hosting; it is delegation to the host under a different name.</p><p>This is the gate. Caching, chunking, compression, certificates (<a href="./0065-derived-artifact-cache-and-compression.html">0065</a>–<a href="./0067-chunk-certificates.html">0067</a>) are packaging and trust optimizations on a <code>Language</code> value. They are meaningless if the <code>Language</code> value cannot yet describe handl itself.</p><h3 id="what-completeness-means-precisely" tabindex="-1">What &quot;completeness&quot; means precisely <a class="header-anchor" href="#what-completeness-means-precisely" aria-label="Permalink to “What &quot;completeness&quot; means precisely”">​</a></h3><p>A <code>Language</code> value <code>L</code> is <strong>self-describing</strong> if:</p><ol><li><code>eval(L, ast_of_L)</code> produces <code>L</code> (or an equivalent <code>Language</code> value) — the language can evaluate the data that defines it.</li><li><code>capabilities(L)</code> contains no <code>Foreign</code> names that refer to host-internal parsing, evaluation, or compilation machinery. <code>Foreign</code> is reserved for genuine host effects (I/O, FFI), per ADR-0044 §4 &quot;Foreign as data, not Rust escape&quot; and ADR-0046&#39;s capability model.</li><li>Every surface construct in the canonical kit desugars to core arrow combinators (<code>arr</code>/<code>&gt;&gt;&gt;</code>/<code>first</code>/<code>choice</code>/<code>loop</code>/<code>app</code>) plus <code>Prim</code> ops whose implementations are themselves expressible as arrow combinators (or are genuine host effects, not language semantics).</li></ol><p>Condition 2 is the sharp edge. <code>Foreign(&quot;eval&quot;)</code> in a self-describing language is a category error: <code>eval</code> is <code>app</code> (dynamic arrow invocation, ADR-0052 §2), not a host function. If the self-description needs <code>Foreign(&quot;eval&quot;)</code>, the core is incomplete.</p><h3 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to “Current state”">​</a></h3><p>The canonical <code>Language</code> (7 YAML files in <code>handl-kit-data-canonical/data/</code>) describes handl&#39;s syntax and eval schemes as data. It is not yet self-describing: the eval schemes for <code>call</code>, <code>var</code> lookup, and <code>object</code> key resolution contain hardcoded Rust logic in the engines (acknowledged as debt in ADR-0058). The arrow-calculus kernel (ADR-0052) is implemented and is the sole <code>Scheme</code> vocabulary, but no <code>handl-defining-handl</code> data file exists, and no proof exists that the kernel + desugar can cover handl&#39;s semantics without <code>Foreign</code> escapes for meta-operations.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-self-hosting-completeness-is-a-proven-property-not-an-aspiration" tabindex="-1">1. Self-hosting completeness is a proven property, not an aspiration <a class="header-anchor" href="#_1-self-hosting-completeness-is-a-proven-property-not-an-aspiration" aria-label="Permalink to “1. Self-hosting completeness is a proven property, not an aspiration”">​</a></h3><p>Before ADR-0044 Phase 8 is considered started, produce a <strong>completeness proof</strong>: a <code>handl-defining-handl</code> data file (or equivalent test artifact) that satisfies the three conditions above. The proof is a test, not a document — <code>self_host.rs</code> (already specified in ADR-0044 Phase 8 testing) is the artifact. This ADR adds the <strong>no-meta-<code>Foreign</code></strong> assertion to that test:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>assert!(capabilities(handl_language)</span></span>
<span class="line"><span>    .host_fns</span></span>
<span class="line"><span>    .iter()</span></span>
<span class="line"><span>    .all(|name| is_genuine_host_effect(name)));</span></span>
<span class="line"><span>assert!(!capabilities(handl_language).host_fns.contains(&quot;eval&quot;));</span></span>
<span class="line"><span>assert!(!capabilities(handl_language).host_fns.contains(&quot;parse&quot;));</span></span>
<span class="line"><span>assert!(!capabilities(handl_language).host_fns.contains(&quot;compile&quot;));</span></span></code></pre></div><p><code>is_genuine_host_effect</code> is defined as: the <code>Foreign</code> name refers to I/O, FFI, or capability-tracked host operations (ADR-0046), <strong>not</strong> to language machinery that belongs in the arrow core.</p><h3 id="_2-audit-and-eliminate-meta-foreign-escapes" tabindex="-1">2. Audit and eliminate meta-<code>Foreign</code> escapes <a class="header-anchor" href="#_2-audit-and-eliminate-meta-foreign-escapes" aria-label="Permalink to “2. Audit and eliminate meta-Foreign escapes”">​</a></h3><p>Inventory every <code>Foreign</code> tag in <code>eval.yaml</code>. Classify each as:</p><ul><li><strong>Genuine host effect</strong> (I/O, FFI, capability-tracked) — keep.</li><li><strong>Meta-operation masquerading as host function</strong> (<code>eval</code>, <code>parse</code>, <code>compile</code>, <code>var</code>-lookup, <code>call</code>-dispatch, key resolution) — eliminate by expressing it as arrow combinators or desugar rules.</li></ul><p>The elimination path for each meta-operation:</p><table tabindex="0"><thead><tr><th>Meta-operation</th><th>Elimination path</th></tr></thead><tbody><tr><td><code>eval</code> (recursive)</td><td><code>app</code> (ADR-0052 §2 — dynamic arrow invocation is the calculus operation, not a host call)</td></tr><tr><td><code>parse</code></td><td>Not an eval operation. Parse is a separate stage (ADR-0044 §2); a self-describing language&#39;s eval schemes never invoke parse.</td></tr><tr><td><code>compile</code></td><td><code>app</code> + handler interpretation (ADR-0052 §2 — external interpretation is the handler&#39;s job). <code>compile</code> as a host function is the Futamura specialization, not a language-internal operation.</td></tr><tr><td><code>var</code> lookup</td><td>Scope chain as arrow state threaded via <code>first</code>/<code>&gt;&gt;&gt;</code>; environments are values, not host lookups.</td></tr><tr><td><code>call</code> dispatch</td><td><code>app</code> (the callee is an arrow value; invocation is <code>app</code>).</td></tr><tr><td>Object key resolution</td><td>Desugar rule (ADR-0058 already specifies this migration).</td></tr></tbody></table><h3 id="_3-desugar-coverage-is-the-primary-completeness-mechanism" tabindex="-1">3. Desugar coverage is the primary completeness mechanism <a class="header-anchor" href="#_3-desugar-coverage-is-the-primary-completeness-mechanism" aria-label="Permalink to “3. Desugar coverage is the primary completeness mechanism”">​</a></h3><p>Surface constructs (<code>match</code>, <code>handle</code>, <code>pipe</code>, <code>ternary</code>, function literals, ...) lower to core combinators via desugar rules (data rewrites, ADR-0044 §4 &quot;Small core + desugar&quot;). The completeness proof requires that <strong>every surface construct in the canonical kit has a desugar rule to core combinators</strong>, with no construct falling back to a <code>Foreign</code> escape.</p><p>If a construct cannot be desugared without <code>Foreign</code>, that is evidence the core is incomplete — either extend the core (a new combinator, versioned per ADR-0044 §7 &quot;Scheme combinator versioning&quot;) or accept that the construct is not self-describable and document it as a known gap. Silently using <code>Foreign</code> is not acceptable.</p><h3 id="_4-the-conformance-suite-is-the-regression-gate" tabindex="-1">4. The conformance suite is the regression gate <a class="header-anchor" href="#_4-the-conformance-suite-is-the-regression-gate" aria-label="Permalink to “4. The conformance suite is the regression gate”">​</a></h3><p>ADR-0044&#39;s cross-engine conformance suite (<code>(Language, Ast, expected Value)</code> triples) is extended with a <strong>self-description corpus</strong>: triples where the <code>Language</code> is <code>handl-defining-handl</code> and the <code>Ast</code>/<code>Value</code> pairs exercise handl&#39;s own constructs. Every eval engine (tree-walk, bytecode, cranelift) must produce identical results on this corpus. A divergence is a self-hosting regression.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to “Positive”">​</a></h3><ul><li><strong>Self-hosting becomes a proven property, not a claim.</strong> The test either passes or it doesn&#39;t; no ambiguity about whether handl &quot;really&quot; describes itself.</li><li><strong>The boundary between language and host is sharp.</strong> <code>Foreign</code> means host effect, full stop. Language machinery lives in the core or desugar layer. This makes ADR-0046&#39;s capability discipline precise: a <code>Language</code> with no genuine host effects is provably safe to eval anywhere.</li><li><strong>Downstream ADRs are unblocked.</strong> Caching, chunking, and certificates (<a href="./0065-derived-artifact-cache-and-compression.html">0065</a>–<a href="./0067-chunk-certificates.html">0067</a>) operate on a <code>Language</code> value that is complete and stable. There is no risk of optimizing a language that later turns out to need <code>Foreign</code> escapes and invalidates the cache/trust model.</li><li><strong><code>app</code> is the sole meta-operation.</strong> <code>eval</code>/<code>compile</code> as host functions are eliminated; <code>app</code> (ADR-0052) is the calculus-native way to invoke an arrow received as data. This is the clean separation ADR-0052 §2 specifies.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to “Negative”">​</a></h3><ul><li><strong>The completeness proof may fail, and fixing it may require core extensions.</strong> If a construct cannot be desugared to the current core without <code>Foreign</code>, the core must be extended (a versioned combinator, ADR-0044 §7) or the construct redesigned. This is real work with an uncertain scope — the ADR-0044 negative consequence acknowledged this.</li><li><strong>Scope chain as arrow state is a non-trivial redesign.</strong> <code>var</code> lookup as host function is the current implementation; expressing it as threaded arrow state changes the eval scheme structure for every binding form. This touches <code>eval.yaml</code> broadly.</li><li><strong>The proof is only as good as the corpus.</strong> A self-description that passes its own tests but misses a construct is a false positive. The corpus must cover every canonical surface construct, not a subset.</li></ul><h3 id="neutral" tabindex="-1">Neutral <a class="header-anchor" href="#neutral" aria-label="Permalink to “Neutral”">​</a></h3><ul><li><strong>This ADR produces no new crates.</strong> It is a property to prove and a constraint to enforce, not a subsystem to build. The artifacts are the <code>handl-defining-handl</code> data file, the extended conformance corpus, and the no-meta-<code>Foreign</code> assertion.</li></ul><h2 id="implementation-phases" tabindex="-1">Implementation phases <a class="header-anchor" href="#implementation-phases" aria-label="Permalink to “Implementation phases”">​</a></h2><h3 id="phase-1-—-foreign-audit" tabindex="-1">Phase 1 — <code>Foreign</code> audit <a class="header-anchor" href="#phase-1-—-foreign-audit" aria-label="Permalink to “Phase 1 — Foreign audit”">​</a></h3><p>Inventory every <code>Foreign</code> tag in <code>eval.yaml</code>. Classify each. Publish the classification as a table in this ADR&#39;s successor or a research note. This is investigation, not implementation.</p><h3 id="phase-2-—-eliminate-meta-foreign-escapes-one-at-a-time" tabindex="-1">Phase 2 — Eliminate meta-<code>Foreign</code> escapes, one at a time <a class="header-anchor" href="#phase-2-—-eliminate-meta-foreign-escapes-one-at-a-time" aria-label="Permalink to “Phase 2 — Eliminate meta-Foreign escapes, one at a time”">​</a></h3><p>For each meta-operation identified in Phase 1, express it as arrow combinators or a desugar rule. Migrate one at a time, with a parity test against the existing Rust implementation (same pattern as ADR-0058&#39;s object-key migration). Order: <code>call</code> dispatch (→ <code>app</code>), <code>var</code> lookup (→ threaded state), then any remaining escapes.</p><h3 id="phase-3-—-handl-defining-handl-data-file" tabindex="-1">Phase 3 — <code>handl-defining-handl</code> data file <a class="header-anchor" href="#phase-3-—-handl-defining-handl-data-file" aria-label="Permalink to “Phase 3 — handl-defining-handl data file”">​</a></h3><p>Author the self-describing <code>Language</code> as a data file. Run it through the extended conformance suite. The no-meta-<code>Foreign</code> assertion must pass.</p><h3 id="phase-4-—-cross-engine-conformance-on-self-description" tabindex="-1">Phase 4 — Cross-engine conformance on self-description <a class="header-anchor" href="#phase-4-—-cross-engine-conformance-on-self-description" aria-label="Permalink to “Phase 4 — Cross-engine conformance on self-description”">​</a></h3><p>Run the self-description corpus against tree-walk, bytecode (when available), and cranelift (when available). Three-way conformance, per ADR-0044 Phase 8.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li><a href="./0044-language-as-data-and-runtime-split.html">ADR-0044</a> — Language as Data and Runtime Split (Phase 8 is the target; §&quot;Negative consequences&quot; is the risk this ADR addresses)</li><li><a href="./0052-arrow-calculus-kernel.html">ADR-0052</a> — Arrow Calculus Kernel (<code>app</code> is the calculus-native meta-operation; <code>vau</code> removed)</li><li><a href="./0058-generic-data-driven-engines.html">ADR-0058</a> — Generic Data-Driven Engines (engines are fixed interpreters; language logic migrates to data)</li><li><a href="./0046-capability-discipline-at-the-language-level.html">ADR-0046</a> — Capability Discipline (<code>Foreign</code> means host effect; this ADR sharpens that definition)</li><li><a href="./0041-languages-as-first-class-values.html">ADR-0041</a> — Languages as First-Class Values (the vision this ADR gates)</li></ul>`,49)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};